const accounts = [
  { name: 'Nathan Van Bignoot', accountId: 'kM4SHffNTGW7DNoIjQLayw' },
  { name: 'Elora Perrin', accountId: '6NPeF8cUS0qBfaRN8jyCjQ' },
  { name: 'Jean-Pierre Martin', accountId: 'yTr-07HvRiuQacAP3ZCiOQ' },
  { name: 'Théo Sonir', accountId: 'tbAlspQ4SJGXMHdYMaOBww' },
  { name: 'Thomas Carnelle', accountId: 'or17KA9LR8W5pfEi4xoiEw' },
  { name: 'Jules Brommet', accountId: 'tW765MO4T8O96FB2qX5YRw' }
];
return accounts.map(a => ({ json: a }));

const now = new Date();
const hour = now.getHours();
const nowMs = now.getTime();

// Etat persistant entre executions du workflow (par compte)
const state = this.getWorkflowStaticData('global');
if (!state.accounts) state.accounts = {};

const results = [];
for (const item of $input.all()) {
  const account = item.json;
  const id = account.accountId;
  if (!state.accounts[id]) {
    // Premiere execution jamais vue pour ce compte : programmer un premier delai aleatoire
    state.accounts[id] = { nextDueAt: 0 };
  }
  const acctState = state.accounts[id];

  // Hors fenetre horaire : on ne touche pas au planning, on attend juste la prochaine iteration dans la fenetre
  if (hour < 8 || hour >= 19) {
    continue;
  }

  if (nowMs >= acctState.nextDueAt) {
    // Ce compte est du : on le laisse passer, et on planifie le PROCHAIN envoi (30-40 min aleatoire)
    const delayMin = Math.floor(Math.random() * 11) + 30; // 30 a 40 min inclus
    acctState.nextDueAt = nowMs + delayMin * 60000;
    results.push({ json: account });
  }
}

return results;

const account = $input.item.json;
const key = "4ZgMv56/.s4NNbHaZRflUeFz92sMBZhSsY5OdCvTnzufcKpLkhwo=";
const base = "https://api43.unipile.com:17313";
let items = [];
let cursor = null;
do {
  const url = base + '/api/v1/chats?account_id=' + account.accountId + '&limit=100' + (cursor ? '&cursor=' + cursor : '');
