} while (cursor);
const contactedIds = new Set(items.map(c => c.attendee_provider_id).filter(Boolean));
return [{ json: { ...account, contactedIds: Array.from(contactedIds) } }];

const account = $input.item.json;
const key = "4ZgMv56/.s4NNbHaZRflUeFz92sMBZhSsY5OdCvTnzufcKpLkhwo=";
const base = "https://api43.unipile.com:17313";

const icpKeywordsByAccount = {
  'kM4SHffNTGW7DNoIjQLayw': ["gerant","gérant","président","president","dirigeant","fondateur","founder","ceo","pdg","proprietaire","propriétaire","menuiserie","batiment","bâtiment","construction","renovation","rénovation","piscine","chauffage","plomberie","toiture","couvreur","paysagiste","energie","énergie"],
  '6NPeF8cUS0qBfaRN8jyCjQ': ["gerant","gérant","président","president","dirigeant","fondateur","founder","ceo","pdg","proprietaire","propriétaire","menuiserie","batiment","bâtiment","construction","renovation","rénovation","piscine","chauffage","plomberie","toiture","couvreur","paysagiste","energie","énergie"]
};
const defaultIcpKeywords = ["fondateur","founder","ceo","agence ia","agence ai","automatisation","freelance","consultant"," ia ","growth","co-fondateur","cofondateur"];
const icpKeywords = icpKeywordsByAccount[account.accountId] || defaultIcpKeywords;

const internalIds = new Set(["ACoAAGZYkcMBBWydKxglJwkY57RrB6yqjYlqhDc","ACoAAEpDSEEBTFRwRgxnyXms6q_rTwBoloNah08","ACoAAGZFSXEBAEhgPdBB--6P4b1zphgC4dn2EfA","ACoAAFpXT2QBSg4TRmULAm8G3xOyNydyJrdU8L4"]);
const contactedIds = new Set(account.contactedIds);

let items = [];
let cursor = null;
do {
  const url = base + '/api/v1/users/relations?account_id=' + account.accountId + '&limit=100' + (cursor ? '&cursor=' + cursor : '');
  const resp = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'X-API-KEY': key }, json: true });
  items = items.concat(resp.items || []);
  cursor = resp.cursor || null;
} while (cursor);

const candidates = items.filter(r => {
  const pid = r.member_id || r.provider_id;
  const headline = (r.headline || '').toLowerCase();
  const isNew = !contactedIds.has(pid) && !internalIds.has(pid);
  const matchesICP = icpKeywords.some(k => headline.includes(k));
  return isNew && matchesICP;
});

if (!candidates.length) return [];
const pick = candidates[0];
return [{ json: { ...account, providerId: pick.member_id || pick.provider_id, publicIdentifier: pick.public_identifier, prenom: pick.first_name, name: (pick.first_name || '') + ' ' + (pick.last_name || ''), headline: pick.headline || '' } }];

const contact = $input.item.json;
const key = "4ZgMv56/.s4NNbHaZRflUeFz92sMBZhSsY5OdCvTnzufcKpLkhwo=";
const base = "https://api43.unipile.com:17313";

const profile = await this.helpers.httpRequest({
  method: 'GET',
  url: base + '/api/v1/users/' + encodeURIComponent(contact.publicIdentifier) + '?account_id=' + contact.accountId + '&linkedin_sections=experience',
  headers: { 'X-API-KEY': key },
  json: true
});

let posts = { items: [] };
try {
  posts = await this.helpers.httpRequest({
    method: 'GET',
    url: base + '/api/v1/users/' + contact.providerId + '/posts?account_id=' + contact.accountId + '&limit=5',
    headers: { 'X-API-KEY': key },
    json: true
  });
} catch(e) {}

return [{ json: { ...contact, profile, posts } }];

const combined = $input.item.json;
const lead = combined.profile;
const contact = combined;
const postsResp = combined.posts;

const prenom = contact.prenom || '';
const headline = contact.headline || '';
const work = (lead.work_experience && lead.work_experience[0]) || {};
const companyName = work.company || '';
const startDate = work.start || '';

function dureeExacte(start) {
  if (!start) return '';
  const parts = start.split('/');
  if (parts.length !== 3) return '';
  const [m, d, y] = parts.map(Number);
  const sd = new Date(y, m - 1, d);
  const now = new Date();
  let months = (now.getFullYear() - sd.getFullYear()) * 12 + (now.getMonth() - sd.getMonth());
  if (months < 12) return months + ' mois';
  const years = Math.floor(months / 12);
  return years + ' an' + (years > 1 ? 's' : '');
}
const dureeReelle = dureeExacte(startDate);
const coverPictureUrl = lead.background_picture_url || '';
const profilePictureUrl = lead.profile_picture_url || '';
const isSelfEmployed = /^(self[- ]?employed|freelance|ind[ée]pendant|auto[- ]?entrepreneur)$/i.test((companyName || '').trim());

const posts = postsResp.items || [];
const twoMonthsAgo = Date.now() - 60 * 86400000;
const parseDate = (v) => {
  if (!v) return 0;
  if (typeof v === 'object') return v.timestamp || (v.date ? new Date(v.date).getTime() : 0);
  return new Date(v).getTime();
};
const recentPosts = posts.filter(p => {
  const dateMs = parseDate(p.date) || parseDate(p.postedAt) || parseDate(p.publishedAt);
  const text = (p.text || '').trim();
  return dateMs > twoMonthsAgo && text.length > 20;
}).slice(0, 1);
const hasPosts = recentPosts.length > 0;
const hasUsableBio = (companyName && dureeReelle) || headline.trim().length > 15;

if (!hasPosts && !hasUsableBio) {
  return [{ json: { ...contact, icebreaker: '', skip: true } }];
}

const isNathanElora = contact.accountId === 'kM4SHffNTGW7DNoIjQLayw' || contact.accountId === '6NPeF8cUS0qBfaRN8jyCjQ';

let systemPrompt, userContent;

if (hasPosts) {
  const postText = (recentPosts[0].text || '').substring(0, 800);
  systemPrompt = "Tu ecris un message LinkedIn complet en reaction au dernier post de cette personne. Message direct, avec un vrai point de vue perso, jamais un compliment vide, comme un pote qui reagit a chaud a ce qu'il vient de lire.\n\nIMPORTANT - orthographe : tu ecris en francais avec tous les accents corrects.\n\nFORMAT (obligatoire) : Helllo [prenom] suivi d'une reaction courte et sincere au post (accord, interet ou amusement selon le ton du post), puis une phrase qui rebondit avec un vrai point de vue personnel, puis OBLIGATOIREMENT une question courte et specifique en lien avec le post pour relancer la conversation.\n\nINTERDIT : contredire frontalement la personne, terminer sans question, formules de politesse generiques, plus d'un point d'exclamation, tiret cadratin, guillemets autour du message, retirer les accents.\n\nTutoie tout du long. Reponds UNIQUEMENT avec le message final complet, rien d'autre.";
  userContent = 'Prenom : ' + (prenom || '(aucun)') + '\nDernier post LinkedIn (publie dans les 2 derniers mois) :\n' + postText;
} else if (isNathanElora) {
  systemPrompt = "Tu ecris un message LinkedIn complet pour une premiere prise de contact, quand la personne n'a aucun post recent a commenter. Message chaleureux, naturel, jamais commercial, comme si un pote t'ecrivait.\n\nIMPORTANT - orthographe : tu ecris en francais avec tous les accents corrects, exactement comme en francais standard.\n\nOn te donne la duree EXACTE depuis laquelle la personne dirige son entreprise/activite, le nom exact de l'entreprise, et une image de son profil LinkedIn si disponible (banniere ou photo). Tu dois utiliser CETTE duree et CE nom exacts, ne jamais en inventer d'autres.\n\nCAS PARTICULIER - personne independante sans societe nommee : dans ce cas, le bloc 2 ne doit JAMAIS dire tu as lance Self-employed. A la place, reformule autour du METIER fourni dans la bio.\n\nFORMAT (obligatoire, exactement 4 blocs separes par une ligne vide) :\n1. Helllo [prenom]\n2. Cas normal : Je vois que ca fait [duree exacte] que tu diriges [nom_entreprise], c'est trop bien ! Cas independant : gabarit alternatif autour du metier.\n3. Exactement sur ce modele : Tu geres plutot des chantiers pour des particuliers en direct, ou aussi pas mal de sous-traitance pour d'autres entreprises du secteur ? (adapte legerement selon le secteur reel de la personne : BTP, renovation, energie, piscine, paysage, toiture, chauffage).\n4. Le PS renvoie TOUJOURS sur une image reelle du profil selon cet ordre : (a) banniere fournie -> detail visuel REEL et PRECIS observe, (b) pas de banniere mais photo de profil -> detail visuel reel de la photo, (c) ni l'un ni l'autre -> PS je me permets de te tutoyer ahah :)\n\nTutoie tout du long.\n\nINTERDIT : plus d'un point d'exclamation, tiret cadratin, compliment vague sur l'image, dire tu as lance Self-employed, guillemets autour du message, retirer les accents francais.\n\nReponds UNIQUEMENT avec le message final complet (les 4 blocs, sauts de ligne inclus), rien d'autre.";
  let bloc2Context = '';
  if (isSelfEmployed) {
    bloc2Context = 'Statut : independant sans societe nommee (champ entreprise = "' + companyName + '")\nDuree exacte reelle : ' + (dureeReelle || '(inconnue)') + '\nActivite / titre (bio) : ' + (headline || '(vide)');
  } else if (companyName && dureeReelle) {
    bloc2Context = 'Nom entreprise/activite : ' + companyName + '\nDuree exacte reelle depuis le lancement : ' + dureeReelle;
  } else {
    bloc2Context = 'Aucune duree/entreprise exacte scrapee. Bio / Headline LinkedIn : ' + (headline || '(vide)');
  }
  let imageNote = '(Ni banniere ni photo de profil disponible pour le PS)';
  if (coverPictureUrl) imageNote = '(Une image de banniere est fournie en piece jointe pour le PS)';
  else if (profilePictureUrl) imageNote = '(Aucune banniere disponible, mais une photo de profil est fournie en piece jointe pour le PS)';
  userContent = 'Prenom : ' + (prenom || '(aucun)') + '\n' + bloc2Context + '\nBio / Headline LinkedIn : ' + (headline || '(vide)') + '\n' + imageNote;
} else {
  systemPrompt = "Tu ecris un message LinkedIn complet pour une premiere prise de contact, quand la personne n'a aucun post recent a commenter. Message chaleureux, naturel, jamais commercial.\n\nIMPORTANT - orthographe : tu ecris en francais avec tous les accents corrects.\n\nFORMAT (obligatoire, exactement 4 blocs separes par une ligne vide) :\n1. Helllo [prenom]\n2. Cas normal : Je vois que ca fait [duree exacte] que tu es [poste] chez [nom_entreprise], c'est trop bien ! Cas independant sans societe nommee : reformule autour du metier/titre de la bio.\n3. Question ciblage/audience du prospect selon son profil, jamais generique sur le produit.\n4. PS renvoie TOUJOURS sur une image reelle du profil : (a) banniere -> detail visuel reel et precis, (b) sinon photo de profil -> detail visuel reel, (c) sinon -> PS je me permets de te tutoyer ahah :)\n\nTutoie tout du long. INTERDIT : plus d'un point d'exclamation, tiret cadratin, compliment vague sur l'image, dire tu as lance Self-employed, guillemets, retirer les accents. Reponds UNIQUEMENT avec le message final complet, rien d'autre.";
  let bloc2Context = '';
  if (isSelfEmployed) {
    bloc2Context = 'Statut : independant sans societe nommee (champ entreprise = "' + companyName + '")\nDuree exacte reelle : ' + (dureeReelle || '(inconnue)') + '\nActivite / titre (bio) : ' + (headline || '(vide)');
  } else if (companyName && dureeReelle) {
    bloc2Context = 'Nom entreprise/activite : ' + companyName + '\nDuree exacte reelle depuis le lancement : ' + dureeReelle;
  } else {
    bloc2Context = 'Aucune duree/entreprise exacte scrapee. Bio / Headline LinkedIn : ' + (headline || '(vide)');
  }
  let imageNote = '(Ni banniere ni photo de profil disponible pour le PS)';
  if (coverPictureUrl) imageNote = '(Une image de banniere est fournie en piece jointe pour le PS)';
  else if (profilePictureUrl) imageNote = '(Aucune banniere disponible, mais une photo de profil est fournie en piece jointe pour le PS)';
  userContent = 'Prenom : ' + (prenom || '(aucun)') + '\n' + bloc2Context + '\nBio / Headline LinkedIn : ' + (headline || '(vide)') + '\n' + imageNote;
}

let aiOutput = '';
try {
  const messageContent = [{ type: 'text', text: userContent }];
  if (!hasPosts) {
    const imageUrlToUse = coverPictureUrl || profilePictureUrl || '';
    if (imageUrlToUse) {
      try {
        const imgResp = await this.helpers.httpRequest({ method: 'GET', url: imageUrlToUse, encoding: 'arraybuffer', returnFullResponse: true });
        const b64 = Buffer.from(imgResp.body).toString('base64');
        messageContent.push({ type: 'image_url', image_url: { url: 'data:image/jpeg;base64,' + b64 } });
      } catch (imgErr) {}
    }
  }
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { 'Authorization': 'Bearer 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', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'anthropic/claude-opus-4', messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: messageContent }], temperature: 0.6, max_tokens: 280 }),
    json: true
  });
  aiOutput = (resp.choices[0].message.content || '').trim();
  if ((aiOutput.startsWith('"') && aiOutput.endsWith('"')) || (aiOutput.startsWith("'") && aiOutput.endsWith("'"))) aiOutput = aiOutput.slice(1, -1);
  aiOutput = aiOutput.replace(/—/g, '-').replace(/–/g, '-');
} catch(e) { aiOutput = ''; }

const icebreaker = aiOutput || '';
const skip = !icebreaker;
return [{ json: { ...contact, icebreaker, hasPosts, skip } }];
